// Editorial source. Steps audited against Minerva 0.4.28 source on 2026-10-15;
// this is not a claim of runtime acceptance of every launcher/source combination.
const articles=[];
function add(slug,category,aliases,ru,en) {
  for(const [locale,row] of [['ru',ru],['en',en]]) {
    const [title,summary,requirements,steps,result,errors,recovery]=row;
    articles.push({slug,locale,title,summary,category,tags:aliases.split('|'),aliases:aliases.split('|'),related:[],minLauncherVersion:'0.4.28',verifiedAt:'2026-10-15',verification:'source',requirements,steps:steps.split('|'),result,errors,recovery});
  }
}
add('install','start','Windows|установка|installation|SmartScreen',
['Установка Minerva на Windows','Скачайте установщик Windows x64 с главной и проверьте его происхождение до запуска.','Нужны Windows x64, свободное место для лаунчера и игры, доступ к сети для первой установки. Объём RAM и Java зависят от версии Minecraft и сборки; фиксированный универсальный минимум не заявлен.','Откройте раздел «Скачать» на главной. Сверьте версию, дату, размер и SHA-256.|Скачайте установщик с minervalauncher.com и сохраните существующие миры перед сменой установки.|Запустите установщик и выберите каталог. Не отключайте защиту Windows ради установки.|Откройте Minerva. Затем настройте игровой профиль и создайте сборку по стартовому гайду.','Открывается экран «Сборки». Само открытие лаунчера ещё не означает, что Minecraft установлен.','Если метаданные загрузки недоступны, повторите запрос позже. Подпись Tauri проверяет обновления и не равна Windows Authenticode: SmartScreen может предупреждать о неизвестном издателе.','При несовпадении хеша не запускайте файл, скачайте его заново. Сохраните папки сборок перед удалением или переустановкой лаунчера.'],
['Install Minerva on Windows','Download the Windows x64 installer from the homepage and check its origin before running it.','Windows x64, space for the launcher and game, and a network connection for initial setup are required. RAM and Java requirements depend on the Minecraft version and pack; no universal minimum is claimed.','Open Download on the homepage. Check the version, date, size and SHA-256.|Download the installer from minervalauncher.com. Back up existing worlds before changing installations.|Run the installer and choose its directory. Keep Windows protection enabled.|Open Minerva, then set up a game profile and create an instance using the first-steps guide.','The Instances screen opens. Opening the launcher does not mean Minecraft has been installed yet.','If release metadata cannot be loaded, retry later. Tauri signatures verify updates; they are separate from Windows Authenticode, so SmartScreen may warn about an unknown publisher.','Do not run a file whose hash differs. Download it again. Preserve instance folders before removing or reinstalling the launcher.']);
add('first-steps','start','первые шаги|начать|start|getting started',
['Первые десять минут','Выберите игровой профиль, создайте отдельную сборку и сначала проверьте простой запуск.','Установлена Minerva 0.4.28 для Windows x64. Для первоначальной подготовки Minecraft нужна сеть; Microsoft-профиль требует соответствующего доступа к игре.','В «Профиль» добавьте Microsoft или локальный игровой профиль. Аккаунт Minerva для облака настраивается отдельно.|Откройте «Сборки» → «+ Новая сборка». Выберите Minecraft и доступный загрузчик, задайте имя.|Проверьте память и Java в настройках сборки. Не выделяйте игре всю память компьютера.|Нажмите «ИГРАТЬ», дождитесь подготовки файлов и проверьте главное меню Minecraft.|Закройте Minecraft. Добавляйте совместимый контент через «Установка контента», выбирая эту сборку.','Есть отдельная сборка, которая запускается с выбранным профилем; затем можно добавлять моды небольшими группами.','Если игра не открывается, смотрите «Логи запуска» и «Диагностика». Сначала проверьте базовый запуск без новых модов, а не меняйте несколько настроек одновременно.','Перед модами, конфигами и обновлением мира сделайте копию папки saves. При проблеме отключите последнюю добавленную группу контента и повторите запуск.'],
['Your first ten minutes','Choose a game profile, create an isolated instance and verify a simple launch first.','Minerva 0.4.28 for Windows x64 is installed. Initial Minecraft preparation needs a network connection; a Microsoft profile needs the relevant game entitlement.','Add a Microsoft or local game profile in Profile. Your Minerva cloud account is configured separately.|Open Instances → + New Instance. Choose Minecraft and an available loader, then enter a name.|Check memory and Java in instance settings. Leave enough memory for Windows and other applications.|Press PLAY, wait for game files to be prepared and verify the Minecraft main menu.|Close Minecraft. Use Install content with this instance selected to add compatible content.','You have a separate instance that launches with your selected profile. Add mods in small groups afterwards.','If the game does not open, inspect Launch logs and Diagnostics. Verify a basic launch before changing several settings at once.','Copy the saves folder before adding mods, changing configuration or upgrading worlds. If a problem starts, disable the most recently added content group and retry.']);
add('profiles','start','профиль|твинки|alt accounts|Microsoft|local accounts',
['Игровые профили и аккаунт Minerva','Игровой профиль определяет игрока в Minecraft, а аккаунт Minerva открывает облачные сохранения и кабинет.','Microsoft и локальные игровые профили поддерживаются отдельно от веб-сессии Minerva. Локальный профиль не предоставляет лицензию и доступ к серверам с проверкой Microsoft.','Откройте «Профиль». Добавьте нужный тип игрового профиля и завершите Microsoft-вход в доверенном окне провайдера, если он выбран.|Выберите активный профиль в переключателе игрока на экране «Сборки».|При необходимости используйте выбор «Запускать с профилем» для конкретной сборки.|Для облачных сборок и биндов отдельно войдите в Minerva в разделе профиля. В браузерном кабинете проверяйте, какой аккаунт подтверждаете.','Игра запускается под выбранным игровым профилем; облачные данные связаны со стабильным аккаунтом Minerva.','Вход Minerva не заменяет вход Microsoft. Если сервер не принимает локальный профиль, не пытайтесь исправить это выходом из веб-кабинета.','При общем компьютере выходите из Minerva и игрового аккаунта отдельно. Не публикуйте коды входа, токены, приватные ссылки или содержимое файлов аккаунтов.'],
['Game profiles and your Minerva account','A game profile identifies the player in Minecraft; a Minerva account enables cloud saves and the account website.','Microsoft and local game profiles are separate from the Minerva web session. A local profile does not grant a game licence or access to servers that require Microsoft authentication.','Open Profile, add the required game-profile type and complete Microsoft sign-in through the trusted provider window when applicable.|Select the active player on the Instances screen.|Use Launch with profile for an individual instance when you want a different default.|Sign in to Minerva separately in Profile for cloud packs and keybinds. Check the account shown when approving browser sign-in.','Minecraft uses the chosen game identity. Cloud data belongs to your stable Minerva account.','Minerva sign-in does not replace Microsoft sign-in. Signing out of the web account will not make a server accept a local game profile.','On shared computers, sign out of Minerva and the game account separately. Never publish sign-in codes, tokens, private links or account files.']);
add('updates','start','обновление|update|stable|preview',
['Обновление и восстановление','Проверяйте номер релиза и сохраняйте игровые данные перед обновлением.','Windows x64. Stable — основной канал; preview может содержать предварительные версии. Совпадение текущих номеров каналов не делает их разными сборками.','Посмотрите текущую версию в лаунчере и заметки в «История обновлений».|Выполните предложенное лаунчером обновление либо скачайте официальный установщик с главной.|Закройте игру перед заменой файлов приложения. Дождитесь завершения установки.|Откройте Minerva и проверьте номер версии, список сборок и простой запуск до изменения игровых файлов.','Лаунчер обновлён; существующие сборки проверены отдельно. Скачивание файла само по себе не доказывает успешное обновление.','При сбое сети повторите загрузку. При ошибке подписи не обходите проверку. Старый GitHub feed может быть мостом на VPS, а не местом хранения установщика.','Сохраните данные и скачайте официальный установщик повторно. Перед откатом проверьте совместимость данных; не заменяйте файлы миров старой копией без собственного бэкапа.'],
['Updates and recovery','Check the release number and preserve game data before updating.','Windows x64. Stable is the main channel; preview may contain prereleases. Identical channel version numbers refer to the same release.','Check the launcher version and read Changelog.|Apply the offered launcher update or obtain the official installer from the homepage.|Close the game before replacing application files. Wait for installation to finish.|Reopen Minerva and check the version, instance list and a basic game launch before modifying game files.','The launcher is updated; existing instances have been checked separately. A downloaded installer alone does not prove an installed update succeeded.','Retry interrupted downloads. Do not bypass a signature failure. The legacy GitHub feed may redirect update metadata to VPS-hosted files.','Preserve data and download the official installer again. Check data compatibility before a rollback; never overwrite worlds with an older copy without a separate backup.']);
add('create-instance','instances','сборка|создание|instance|Java|RAM',
['Создание сборки: версия, загрузчик, Java и память','Каждая инстанция хранит игровые данные отдельно; выбирайте загрузчик под свои моды.','Доступные сочетания Minecraft и загрузчика определяются каталогом. Поддержка одного Fabric-релиза не означает поддержку всех исторических версий.','На экране «Сборки» нажмите «+ Новая сборка».|Укажите имя, версию Minecraft, загрузчик и доступную версию загрузчика.|Проверьте источник общих настроек и параметры Java/памяти. Для независимых настроек используйте собственный источник.|Создайте сборку и нажмите «ИГРАТЬ». Дождитесь установки runtime и проверьте главное меню.','Сборка имеет собственную папку и подготовленный runtime после успешного первого запуска.','Мод для Forge не становится Fabric-модом при смене загрузчика. Неподходящая Java и чрезмерная память могут мешать запуску; диагностируйте по логу.','Перед сменой версии сохраните saves/config/options. Для эксперимента создайте отдельную сборку, чтобы исходная оставалась доступна.'],
['Create an instance: version, loader, Java and memory','Instances keep game data separate. Select a loader that matches your mods.','Available Minecraft and loader combinations come from the catalog. Support for one Fabric release does not imply support for every historical version.','Press + New Instance on Instances.|Enter a name, Minecraft version, loader and an available loader version.|Check the common-settings source and Java/memory settings. Use an independent settings source when isolation is required.|Create the instance and press PLAY. Wait for runtime preparation and verify the main menu.','The instance has its own directory, with its runtime prepared after a successful first launch.','Changing loaders does not turn a Forge mod into a Fabric mod. Unsupported Java or excessive memory allocation can prevent startup; use the log to diagnose it.','Back up saves/config/options before changing versions. Use a separate instance for experiments so the original stays available.']);
add('migration-modrinth','instances','перенос|migration|Modrinth|import',
['Перенос из Modrinth','Minerva создаёт независимую копию поддерживаемых игровых данных, сохраняя оригинал.','Закройте Minecraft в Modrinth. Нужны место для копии и резерв свободного места; неизвестные метаданные требуют ручного выбора. Реальную сборку сначала сохраните отдельно.','Откройте «Сборки» → «Импорт» → «Из другого лаунчера».|Выберите обнаруженную сборку Modrinth. Для нестандартного расположения укажите папку вручную.|В предварительном просмотре проверьте исходную gamePath, версию Minecraft/загрузчика, включённые и непереносимые папки, размер.|Подтвердите «Minecraft в исходном лаунчере закрыт» и нажмите «Скопировать в Minerva».|После копирования запустите новую сборку: Minecraft, Java и библиотеки подготовит Minerva. Сравните миры, моды и настройки.','Оригинал не перемещается и не удаляется. Учётные записи, launch hooks, чужие Java и команды запуска не импортируются.','Если обнаружение не нашло переносимую/новую структуру, выберите каталог вручную. При ошибке изменения источника закройте игру и начните копирование заново.','Не удаляйте исходную сборку до проверки копии. Прерванный импорт папки перезапускается с источника; это другой механизм, чем продолжение установки .minerva.'],
['Migrate from Modrinth','Minerva creates an independent copy of supported game data and preserves the original.','Close Minecraft in Modrinth. Allow space for the copy plus a free-space reserve. Unknown metadata requires manual selection. Back up the original pack separately first.','Open Instances → Import → From another launcher.|Select the detected Modrinth instance, or choose its folder for a custom installation.|Check the source gamePath, Minecraft/loader version, included and omitted entries, and copy size in the preview.|Confirm Minecraft in the source launcher is closed and press Copy to Minerva.|Launch the new instance so Minerva prepares Minecraft, Java and libraries. Compare worlds, mods and settings.','The source is not moved or deleted. Launcher accounts, launch hooks, external Java runtimes and launch commands are not imported.','If a portable installation or new metadata layout is not detected, choose the directory manually. If the source changed during copying, close the game and restart the copy.','Keep the source until the new copy is verified. An interrupted folder import restarts from its source; it does not use the .minerva installation-resume mechanism.']);
add('migration-tl','instances','тл|TL|TLauncher|перенос|migration',
['Перенос из TL: как выбрать gameDir','Выберите именно каталог игровых данных нужной сборки, а не любую папку с номером версии.','Minecraft должен быть закрыт. У TL встречаются общий .minecraft и отдельные каталоги версий. Не обещается перенос всех модифицированных клиентов или чужих launch hooks.','Откройте «Сборки» → «Импорт» → «Из другого лаунчера». Выберите найденный TL-источник или укажите папку.|Сверьте gamePath в просмотре. Для общей .minecraft проверьте, что saves/mods/config относятся к нужной игре; отдельная версия может хранить их в своём gameDir.|Проверьте включённые/непереносимые файлы. Если версия или загрузчик не распознаны, укажите их вручную по исходной сборке.|Подтвердите закрытый Minecraft и выберите «Скопировать в Minerva».|При первом запуске дождитесь подготовки runtime, затем сравните миры, настройки и контент.','Создаётся отдельная копия поддерживаемых данных. Скины, аккаунты и специфические механизмы чужого лаунчера не переносятся как его runtime.','Пустая папка versions/<id> не обязательно содержит игровые данные. Если в просмотре нет ожидаемых миров/модов, отмените и найдите правильный gameDir.','Сохраните оригинал. При сбое начните копирование заново после закрытия игры. TL-сценарии требуют проверки на вашей конкретной структуре; тестовые fixtures не доказывают совместимость всех вариантов.'],
['Migrate from TL: choose the right gameDir','Choose the directory containing the intended pack’s game data, rather than any folder named after a version.','Close Minecraft first. TL installations may use a shared .minecraft or an isolated version directory. Support for every patched client or external launch hook is not promised.','Open Instances → Import → From another launcher. Select a detected TL source or choose its folder.|Check gamePath in the preview. With shared .minecraft, verify that saves/mods/config belong to the intended game; an isolated version may keep them in its own gameDir.|Review included and omitted files. If Minecraft or loader metadata is missing, specify the original versions manually.|Confirm the source game is closed and select Copy to Minerva.|On first launch, wait for runtime preparation, then compare worlds, settings and content.','A separate copy of supported game data is created. Skins, accounts and launcher-specific mechanisms are not imported as an external runtime.','A versions/<id> directory may contain metadata without game data. If expected worlds or mods are absent from the preview, cancel and locate the correct gameDir.','Keep the original. Restart failed copying after closing the game. Check your actual TL layout: fixture tests do not establish compatibility with every variant.']);
add('archive-import','instances','ZIP|MRPACK|архив|archive',
['Импорт ZIP и MRPACK','Архив игровых файлов и Modrinth-манифест — разные источники импорта.','Нужен доверенный архив, свободное место и сеть для файлов, которые не включены в MRPACK. Содержимое стороннего архива может быть несовместимым.','Выберите «Сборки» → «Импорт» → «Архив (.zip / .mrpack)».|Укажите файл и имя будущей сборки. Проверьте доступную информацию о версии и загрузчике.|Запустите импорт и дождитесь его завершения. Для MRPACK недостающий контент скачивается по манифесту.|Перед открытием своего мира проверьте запуск новой сборки и установленный контент.','Создана новая сборка из поддерживаемой структуры архива. MRPACK не является полным бэкапом всех личных данных.','Произвольный ZIP всего диска или архива другого лаунчера может не иметь нужной структуры. Ошибки скачивания и несовместимость модов требуют отдельного разбора.','Не заменяйте исходные миры. Сохраните архив и копию saves; если импорт не завершился, проверьте ошибку и повторите без удаления рабочих сборок.'],
['Import ZIP and MRPACK','A game-data archive and a Modrinth manifest are different import sources.','Use a trusted archive, enough disk space and a connection for files not bundled in the MRPACK. External archive contents may be incompatible.','Choose Instances → Import → Archive (.zip / .mrpack).|Select the file and a name for the new instance. Review available Minecraft and loader metadata.|Start import and wait for completion. Missing MRPACK content is downloaded according to its manifest.|Test the new instance and its content before opening your own world.','A new instance is created from a supported archive structure. An MRPACK is not a complete backup of all personal data.','An arbitrary disk ZIP or another launcher’s archive may not have a supported layout. Download failures and mod incompatibilities need separate investigation.','Preserve original worlds, the archive and a saves backup. If import fails, inspect the error and retry without deleting working instances.']);
add('backups','instances','ZIP|экспорт|backup|миры|saves',
['Локальный экспорт и резервные копии','ZIP может включать выбранные игровые папки; состав нужно проверить до удаления оригинала.','Закройте Minecraft, особенно перед копированием миров. .minerva и облачный манифест не включают миры и не заменяют этот бэкап.','В дополнительных действиях нужной сборки откройте экспорт.|Выберите папки для ZIP, включая saves, если нужны миры. Проверьте включение config, options и другого важного содержимого.|Нажмите «Сохранить ZIP» и сохраните архив за пределами исходной папки.|Откройте список файлов архива и убедитесь, что важные папки присутствуют. Проверьте восстановление в отдельную тестовую сборку.|Для защиты от потери диска храните дополнительную копию на другом носителе.','Есть проверенная копия выбранных данных; полнота определяется вашим выбором папок.','Наличие файла ZIP не доказывает, что в него вошли миры. Копирование активного мира может дать несогласованные данные.','Восстанавливайте сначала в новую папку/сборку. Сохраните текущие данные отдельно перед заменой; не распаковывайте поверх единственной рабочей копии.'],
['Local export and backups','A ZIP can include selected game folders. Check its contents before deleting the source.','Close Minecraft, especially before copying worlds. Neither .minerva nor a cloud manifest includes worlds or replaces this backup.','Open export from the instance’s additional actions.|Select ZIP folders, including saves for worlds. Check whether config, options and other required data are included.|Press Save ZIP and store the archive outside the source directory.|Inspect the archive’s file list and verify required folders. Test restoration into a separate instance.|Keep an additional copy on another device to protect against disk loss.','You have a verified copy of the selected data. Its completeness depends on the folders you chose.','A ZIP file alone does not prove worlds were included. Copying an active world can produce inconsistent data.','Restore into a new directory or instance first. Preserve current data before replacement; do not extract over your only working copy.']);
add('instance-settings','instances','настройки|settings|common|options',
['Настройки сборки и общий источник','Проверьте источник настроек перед изменением: связанные сборки могут использовать общие параметры.','Назначение источника настроек и копирование игровых данных — разные операции. Закройте игру и сохраните config/options перед их заменой.','Откройте настройки нужной сборки из её дополнительных действий.|Посмотрите, является ли она источником или использует настройки другой сборки. Сверьте это с отметкой на карточке.|Измените Java/память только после проверки выбранного источника. Не назначайте общие настройки случайно рабочим сборкам.|Для переноса игровых options/config сначала сделайте копию файлов и переносите только совместимые параметры при закрытой игре.|Запустите сборку, проверьте применённые настройки, затем отдельно проверьте другие связанные сборки.','Источник общих настроек выбран осознанно; локальные файлы не считаются автоматически совместимыми между версиями.','Похожая настройка в двух версиях может иметь другой формат. Копирование options.txt целиком может затронуть графику и управление.','Верните сохранённые config/options при закрытом Minecraft. Для биндов используйте отдельный механизм восстановления с предпросмотром, а не замену всего options.txt.'],
['Instance settings and shared sources','Check the settings source before editing: linked instances may share parameters.','Selecting a settings source is separate from copying game files. Close the game and back up config/options before replacement.','Open the intended instance’s settings from its additional actions.|Check whether it is a settings source or inherits from another instance. Compare the label on its card.|Adjust Java/memory only after checking the selected source. Avoid accidentally assigning common settings to working instances.|To copy game options/config, first preserve the files and transfer only compatible settings while the game is closed.|Launch the instance and check applied settings, then check other linked instances separately.','The shared-settings source is intentional. Local configuration files are not assumed compatible across versions.','A similarly named setting may use a different format in another version. Copying options.txt wholesale can affect both graphics and controls.','Restore backed-up config/options with Minecraft closed. For keybinds, use the dedicated preview-and-restore workflow instead of replacing all of options.txt.']);
add('install-content','content','Modrinth|CurseForge|моды|ресурспаки|shader|mods',
['Установка модов, ресурспаков и шейдерпаков','Выбирайте контент для версии Minecraft и загрузчика целевой сборки.','Нужны существующая сборка и сеть. Доступность файлов зависит от каталога; наличие шейдерпака не устанавливает автоматически совместимый shader loader.','Откройте «Установка контента» и выберите целевую сборку.|Выберите тип контента, источник Modrinth/CurseForge и найдите проект.|Просмотрите доступную версию и совместимость. Устанавливайте зависимости по показанным рекомендациям.|Подтвердите установку. Не используйте «Скачать всё равно» как обычный способ обойти предупреждения.|Запустите сборку и включите ресурспак/шейдер в игре, если соответствующая система поддерживается.','Файлы установлены в выбранную сборку; итоговую совместимость проверяет запуск.','Каталог может не иметь файла для вашей версии. Предупреждение о неизвестной совместимости не означает, что мод заведомо подходит.','Перед изменением контента сохраните миры и config. Отключите последнюю установленную группу при сбое, затем проверяйте зависимости по отчёту.'],
['Install mods, resource packs and shader packs','Choose content for the target instance’s Minecraft version and loader.','An existing instance and connection are required. Catalog availability varies. A shader pack does not automatically install a compatible shader loader.','Open Install content and select the target instance.|Choose the content type and Modrinth/CurseForge source, then find a project.|Review its available version and compatibility. Install dependencies using the displayed recommendations.|Confirm installation. Download anyway is an explicit risk decision, not a routine way to dismiss warnings.|Launch the instance and enable the resource or shader pack in game where the required system is supported.','Files are installed in the selected instance. Actual compatibility still requires a game launch.','The catalog may have no file for your version. Unknown compatibility does not mean a mod is known to work.','Preserve worlds and config before content changes. Disable the latest installed group after a failure, then inspect the dependency report.']);
add('manage-content','content','версии модов|disable|versions|content management',
['Управление установленным контентом','Поиск, фильтры и переключатели помогают менять контент небольшими проверяемыми шагами.','Откройте нужную сборку; операции версий зависят от известного каталожного проекта и доступных файлов. Не все локальные JAR имеют такое происхождение.','На карточке сборки откройте «Моды» и найдите установленный файл поиском/фильтрами.|Для временного исключения используйте выключение контента. Затем проверьте, не отключилась ли обязательная библиотека.|Для замены версии просмотрите доступные версии и совместимость. Используйте удаление/возврат версии только там, где действие доступно.|После изменения запустите проверку зависимостей и Minecraft. Записывайте, какой набор изменений проверяли.','Список отражает установленный и включённый контент. Отключение файла отличается от его удаления.','Локальный файл может быть неизвестен каталогу, поэтому список версий не гарантирован. Две версии одного мода могут создавать дубликат.','Сохраните копию заменяемых файлов и config. При сбое отключите новую версию и верните предыдущую совместимую, не оставляя обе активными.'],
['Manage installed content','Search, filters and toggles help you make small, verifiable content changes.','Open the correct instance. Version actions depend on known catalog identity and available files; not every local JAR has that provenance.','Open Mods on the instance card and find a file using search/filters.|Temporarily disable content using its toggle. Check that required libraries remain enabled.|Review compatibility before selecting another available version. Use removal/version-return actions only where offered.|After changes, check dependencies and launch Minecraft. Keep a record of the set of changes you tested.','The list reflects installed and enabled content. Disabling a file differs from deleting it.','An unknown local file may have no catalog version history. Two active versions of one mod can create a duplicate.','Preserve replaced files and config. After a failure, disable the new version and restore the previous compatible one without leaving both active.']);
add('repair','content','fabric-api|фабрик апи|зависимости|repair|dependencies',
['Проверка и починка зависимостей','Используйте конкретные действия отчёта: включить библиотеку, установить известную зависимость, разобрать конфликт.','Minerva 0.4.28. Для загрузки известных файлов нужна сеть. Проверка не гарантирует отсутствие всех runtime-конфликтов или ошибок самого мода.','На карточке выберите «Исправить» и дождитесь отчёта управляемых файлов.|Откройте группу проблемы. Если нужный Fabric API или другая библиотека выключена, включите её.|Если зависимость известна и доступна, используйте предложенную установку. Сверьте версию Minecraft/загрузчика.|Для дубликатов и несовместимости сохраните копию и отключите конфликтующие файлы по одному.|Повторите проверку и запуск. Неизвестную зависимость решайте вручную по сообщению мода.','Исправлены конкретные выявленные проблемы. Игнорирование предупреждения не считается исправлением.','Группировка нескольких модов по одной библиотеке не означает несколько разных ошибок. Отсутствие известного файла в каталоге требует ручного решения.','Перед заменой сохраните моды, config и миры. Если после ремонта стало хуже, верните последнюю изменённую группу и приложите обезличенный отчёт разработчику.'],
['Check and repair dependencies','Use the report’s concrete actions: enable a library, install a known dependency or investigate a conflict.','Minerva 0.4.28. Downloading known files requires a connection. Checks cannot guarantee the absence of all runtime conflicts or bugs inside mods.','Choose Repair on the instance card and wait for the managed-file report.|Expand a problem group. Enable required Fabric API or another library if it is disabled.|For a known available dependency, use the offered installation action and check Minecraft/loader versions.|For duplicates and incompatibilities, preserve a copy and disable conflicting files one at a time.|Repeat the check and launch. Resolve unknown dependencies manually using the mod’s error message.','Specific detected problems have been addressed. Ignoring a warning is not a repair.','Several mods grouped under one dependency do not necessarily represent separate errors. Missing catalog files may require manual action.','Preserve mods, config and worlds before replacement. If repair worsens the result, restore the latest changed group and send a redacted report to the developer.']);
add('startup-errors','content','не запускается|crash|ошибка|Java|logs',
['Игра не запускается','Сначала сохраните точную ошибку и выясните, на каком этапе остановился запуск.','Не удаляйте сборку или мир ради диагностики. Сверьте Minecraft, загрузчик, Java и память с требованиями контента.','Откройте «Логи запуска» после неудачной попытки и запишите последнюю понятную ошибку.|Посмотрите «Диагностика» и отчёт «Исправить» для этой сборки.|Если проблема началась после мода, выключите последнюю добавленную группу; проверьте библиотеки и дубликаты.|Проверьте Java/память. Сначала повторите запуск без изменения нескольких параметров сразу.|Если не удалось разобраться, отправьте обращение с версией, шагами и безопасным фрагментом ошибки.','Есть воспроизводимый случай и проверенная гипотеза, а не случайный набор переустановок.','Токены, адреса приватных серверов и пользовательские пути могут попасть в лог. Не вставляйте его целиком без просмотра.','Закройте игру и верните сохранённые моды/config. Открывайте важный мир только после проверки меню и копии мира на совместимость.'],
['Minecraft will not start','Preserve the exact error first and identify the stage where launching stops.','Do not delete an instance or world for diagnosis. Compare Minecraft, loader, Java and memory settings with your content’s requirements.','Open Launch logs after the failed attempt and record the last meaningful error.|Inspect Diagnostics and the instance’s Repair report.|If a recent mod triggered the problem, disable that group and check libraries and duplicates.|Check Java/memory. Retry while changing one setting at a time.|If unresolved, send a support request with the version, reproduction steps and a safe error excerpt.','You have a reproducible case and a tested hypothesis instead of unrelated reinstalls.','Logs may contain tokens, private server addresses and personal file paths. Review them before sharing, rather than pasting an entire log blindly.','Close the game and restore preserved mods/config. Open an important world only after testing the menu and checking a copy of that world for compatibility.']);
add('resume','content','нет интернета|resume|retry|продолжить|пропуск|network',
['Сбой сети и продолжение установки','Продолжайте незавершённую установку манифеста в ту же целевую сборку.','Этот механизм относится к установке .minerva по файлам; прерванное копирование чужой папки запускается заново. Не меняйте target случайно.','В окне установки посмотрите, какой файл завершился ошибкой. Уже сохранённые успешные файлы остаются в выбранной цели.|Восстановите соединение и используйте повтор для проблемного файла.|Если решили пропустить файл, прочитайте, обязателен ли он. Пропуск обязательного файла оставляет сборку незавершённой.|Найдите незавершённую установку и продолжите её с тем же target, сохранив выбор компонентов.|После завершения проверьте отчёт отсутствующих файлов и запуск.','Успешно подготовленные файлы используются повторно; готовность зависит от обязательных компонентов.','Повтор в новую сборку создаёт другую цель и не продолжает прежнюю. Недоступный/удалённый файл может остаться недостающим после восстановления сети.','Не очищайте папку с успешно установленными файлами. Сохраните список отсутствующих и данные цели, чтобы повторить или заменить недоступный компонент осознанно.'],
['Network failures and installation resume','Resume an unfinished manifest installation into the same target instance.','This per-file workflow applies to .minerva installation. Interrupted foreign-folder copying restarts instead. Do not accidentally switch targets.','Check which file failed in the installation dialog. Successful files remain in the selected target.|Restore the connection and retry the failed file.|If skipping it, check whether it is required. Skipping a required file leaves the instance incomplete.|Find the unfinished installation and continue with the same target and component selection.|When finished, review missing files and test launching.','Successfully prepared files are reused. Readiness depends on required components.','Choosing a new instance creates a different target instead of resuming the old installation. A removed or inaccessible file may remain missing after the connection recovers.','Keep successfully installed files. Preserve the missing-file list and target details so you can retry or deliberately replace an unavailable component.']);
add('manifest','cloud','minerva|manifest|манифест|backup',
['Что хранит файл .minerva','Это переносимый список доступного каталожного контента, а не архив вашей игры.','Schema 1 хранит ссылки на конкретные проекты/версии/хеши. Миры, бинарники, приватные конфиги и бинды в облачный манифест не загружаются.','В дополнительных действиях сборки откройте сохранение/загрузку пака.|Просмотрите включённые файлы и раздел пропущенного. Неизвестные, приватные или недоступные файлы могут не войти.|Сохраните локальный .minerva либо выберите облачное сохранение.|Для восстановления откройте «Импорт» → «Файл манифеста (.minerva)», выберите компоненты и цель.|Для миров и личных настроек отдельно создайте локальный ZIP-бэкап.','Манифест позволяет повторно загрузить доступные закреплённые файлы. Сам файл не хранит их содержимое.','Совпадение имени JAR не доказывает происхождение; важны проект, версия и точные байты/хеш. Недоступность источника может мешать восстановлению.','Сохраните оригинальную сборку и ZIP нужных данных. Проверяйте восстановление манифеста в отдельной цели до удаления исходных файлов.'],
['What a .minerva file contains','It is a portable list of available catalog content, rather than an archive of your game.','Schema 1 pins projects, versions and hashes. Worlds, binaries, private configs and keybinds are not uploaded in a cloud manifest.','Open pack save/restore from the instance’s additional actions.|Review included and omitted entries. Unknown, private or unavailable files may be excluded.|Save a local .minerva file or choose cloud storage.|To restore, use Import → Manifest file (.minerva), then select components and a target.|Create a separate local ZIP backup for worlds and personal settings.','The manifest can download available pinned files again. It does not contain the files themselves.','A matching JAR name does not establish provenance: project, version and exact bytes/hash matter. Source availability can affect restoration.','Keep the original instance and a ZIP of required personal data. Test manifest restoration into a separate target before removing source files.']);
add('cloud-save','cloud','облако|cloud|two slots|две сборки',
['Сохранить или обновить облачную сборку','Бесплатно доступны два облачных слота; обновление существующего сохраняет его место.','Войдите в Minerva в «Профиль». Сохраняется schema-1 манифест, а не миры и приватные конфиги. Интернет нужен для облачных операций.','Откройте облачные сборки в «Профиль» и выберите исходную инстанцию.|Чтобы занять свободный слот, используйте сохранение новой сборки из выбранной инстанции и проверьте состав.|Чтобы заменить уже сохранённую сборку, у нужной строки нажмите «Обновить сохранение»: это новая ревизия того же слота.|Сверьте название, Minecraft/загрузчик, номер ревизии и даты. При конфликте ревизий обновите список перед повтором.|Если оба слота заняты, обновите один из них либо удалите ненужную сборку после проверки её ссылок.','В кабинете и лаунчере виден актуальный манифест. Локальные .minerva не ограничены этими двумя облачными слотами.','«Создать ещё один» расходует слот, «Обновить сохранение» — нет. Удаление облачной сборки отзывает её активные ссылки.','Сохраните локальный .minerva до удаления. Уже выданная ссылка относится к прежнему снимку и не обновляется вместе с исходной облачной сборкой.'],
['Save or update a cloud pack','Two free cloud slots are available. Updating an existing save keeps the same slot.','Sign in to Minerva in Profile. Cloud saves contain a schema-1 manifest, not worlds or private configs. Cloud operations require a connection.','Open cloud packs in Profile and select a source instance.|To use a free slot, save a new pack from the selected instance and review its contents.|To replace a saved pack, press Update save on its existing row. This creates a new revision in the same slot.|Check its name, Minecraft/loader, revision and dates. Refresh the list before retrying a revision conflict.|If both slots are occupied, update one or remove an unused save after checking its links.','The account and launcher show the current manifest. Local .minerva files do not use the two cloud slots.','Creating another save uses a slot; Update save does not. Deleting a cloud pack revokes its active share links.','Keep a local .minerva before deletion. An existing share link points to its earlier snapshot and does not change when the original cloud pack is updated.']);
add('share','cloud','share|link|поделиться|ссылка|friend',
['Поделиться сборкой и отозвать ссылку','Приватная ссылка даёт доступ к снимку конкретной ревизии, а не к меняющемуся оригиналу.','Нужна сохранённая облачная сборка. До пяти активных ссылок на сборку. Доступ по секретной ссылке не является шифрованием содержимого.','В облачных сборках найдите нужную ревизию и нажмите «Создать ссылку».|Скопируйте полученную ссылку целиком, включая fragment после #. Передавайте только нужному человеку.|Проверьте показанную версию снимка. Обновление сохранения не изменяет старые ссылки.|Чтобы закрыть доступ, откройте «Активные ссылки» и отзовите нужную; удаление сборки отзывает все её ссылки.','Друг может открыть этот снимок. Уже скачанную копию невозможно отозвать.','Потерянный fragment или отозванная ссылка делают доступ недоступным. Не вставляйте приватную ссылку в публичные логи или обращения.','Перед отзывом при необходимости создайте новую ссылку для нужного человека. Не рассчитывайте на отзыв как на удаление копий с чужих компьютеров.'],
['Share a pack and revoke a link','A private link grants access to a snapshot of one revision, rather than a changing original.','A saved cloud pack is required. Up to five active links per pack are allowed. Secret-link access does not encrypt the content.','Find the intended cloud revision and press Create link.|Copy the entire link, including the fragment after #, and share it only with the intended person.|Check the snapshot version. Updating the save does not update old links.|To end access, open Active links and revoke the selected link. Deleting the pack revokes all its links.','Your friend can open that snapshot. Copies already downloaded cannot be revoked.','A missing fragment or revoked link makes the share unavailable. Do not include private links in public logs or support requests.','Create a replacement link for the intended recipient if needed. Revocation does not delete copies from other computers.']);
add('cloud-restore','cloud','установить сборку|cloud restore|friend link|target',
['Установить из облака или ссылки друга','Выберите компоненты и целевую инстанцию до скачивания файлов.','Личное облако требует входа Minerva. Ссылка друга должна содержать полный секретный fragment. Открытие чужой ссылки само по себе не занимает облачный слот.','Выберите «Сборки» → «Импорт» → «Мои облачные сборки» либо «Ссылка друга».|Выберите сохранение или вставьте полную ссылку и нажмите «Открыть сборку».|Проверьте манифест, версии и отсутствующие файлы. Выберите компоненты и target, сохранив данные существующей цели заранее.|Запустите установку и следите за прогрессом файлов. Используйте повтор при временном сбое.|Если установка незавершена, продолжите в тот же target. Проверьте запуск после обязательных файлов.','Файлы подготовлены в выбранной цели. Свой облачный слот используется только при отдельном явном сохранении копии.','Пропуск обязательного файла не делает сборку готовой. Ссылка может быть отозвана; обновление исходной облачной сборки не меняет снимок по ссылке.','До установки в существующую цель сохраните mods/config/saves. Не удаляйте успешные файлы при временной сетевой ошибке; сохраните список недостающего.'],
['Install from cloud or a friend’s link','Select components and the target instance before downloading files.','Personal cloud access needs Minerva sign-in. A friend’s link must include its full secret fragment. Opening a shared link alone does not use a cloud slot.','Choose Instances → Import → My cloud packs or Friend’s link.|Select a save or paste the complete link and press Open pack.|Review the manifest, versions and missing entries. Select components and a target; back up an existing target first.|Start installation and follow per-file progress. Retry temporary failures.|Resume an unfinished installation into the same target. Test launching after required files are prepared.','Files are prepared in the selected target. A cloud slot is used only if you explicitly save your own cloud copy.','Skipping a required file leaves the instance incomplete. A share can be revoked; changes to the source cloud pack do not change its linked snapshot.','Back up mods/config/saves before installing into an existing target. Keep successful files after temporary network errors and preserve the missing-file list.']);
add('missing-files','cloud','missing|недостающие|unavailable|совместимость',
['Недоступные файлы и неподтверждённая совместимость','Отчёт отсутствующего — часть результата, которую нужно проверить до запуска.','Файл мог быть приватным, удалённым, неизвестным каталогу или недоступным для выбранной версии. Это не исправляется переименованием JAR.','Откройте просмотр манифеста/результат установки и раздел отсутствующих файлов.|Скопируйте список недостающего, если действие доступно. Сохраните причину и требуемую версию.|Проверьте официальный источник проекта и точное соответствие Minecraft/загрузчика. Не подменяйте файл случайной похожей версией.|При неподтверждённой совместимости решите, готовы ли вы к риску; «Скачать всё равно» требует отдельного подтверждения.|Повторите проверку зависимостей и тестовый запуск без важного мира.','Есть точный список того, что восстановлено и что требует ручного решения.','Зелёный прогресс скачивания не подтверждает совместимость всего пака. Локальный неизвестный мод может не войти в облачный манифест.','Оставьте исходную сборку и копию мира. Верните прежнюю версию, если замена не подходит, и не объявляйте неполный пак готовым.'],
['Unavailable files and unconfirmed compatibility','Review the missing-file report as part of the installation result before launching.','Files may be private, removed, unknown to the catalog or unavailable for the chosen version. Renaming a JAR does not resolve this.','Open the manifest preview or installation result and inspect missing entries.|Copy the missing-file list where offered. Preserve each reason and requested version.|Check the project’s official source and exact Minecraft/loader match. Avoid substituting an arbitrary similar version.|For unconfirmed compatibility, decide whether to accept the risk. Download anyway requires separate confirmation.|Repeat dependency checks and test without an important world.','You have an exact record of restored content and entries needing manual resolution.','Completed download progress does not establish whole-pack compatibility. Unknown local mods may be omitted from a cloud manifest.','Keep the source pack and a world copy. Restore the previous version if a substitute fails, and do not mark an incomplete pack as ready.']);
add('keybinds','cloud','бинды|binds|keybinds|управление|controls',
['Сохранение и восстановление биндов','Наборы управления хранятся отдельно от манифеста; доступны до десяти наборов.','Войдите Minerva. Закройте Minecraft перед чтением/записью options. Сборка должна хотя бы раз создать настройки при первом запуске.','Откройте «Профиль» → «Бинды». Выберите «Сохранить из инстанции» и «Сохранить в аккаунте». Подтвердите замену существующего набора, если она предложена.|В «Сохранённые наборы» найдите источник по имени, версии и датам. Выберите набор и целевую сборку.|Просмотрите совпадающие бинды и несовместимые записи. Для другой версии прочитайте первое предупреждение о несовпадении.|Перед записью подтвердите второе предупреждение о переносе между версиями. Это осознанное согласие, а не гарантия одинаковых действий.|Проверьте управление в игре. Удаляйте ненужный набор только после проверки источника.','Поддерживаемые совпадающие бинды перенесены; остальные графические/игровые options не заменяются целиком.','Отсутствующий options требует первого запуска. Нет совпадающих биндов — перенос недоступен; лимит десяти требует удаления ненужного набора.','Перед восстановлением сохраните options.txt цели. Если управление неверно, закройте игру и верните копию либо восстановите прежний набор.'],
['Save and restore keybinds','Control sets are stored separately from manifests, with up to ten saved sets.','Sign in to Minerva. Close Minecraft before reading/writing options. The instance must have created settings through an initial launch.','Open Profile → Bindings. Select Save from instance and Save to account. Confirm replacement if a set already exists.|Find the source in Saved sets using its name, version and dates. Select it and the target instance.|Review matching bindings and incompatible entries. For another game version, read the first version-mismatch warning.|Before writing, confirm the second cross-version transfer warning. Consent does not guarantee identical actions between versions.|Check controls in game. Remove unused sets only after checking their source.','Supported matching bindings are transferred without replacing all other graphics/game options.','Missing options require a first launch. No matching bindings means restoration cannot proceed. The ten-set limit requires removing an unused set.','Preserve the target options.txt first. If controls are wrong, close the game and restore the copy or a previously saved set.']);
add('warm-return','profiles','Warm Return|RAM|ожидание|ready in memory',
['Warm Return и полный выход','Warm Return сохраняет поддерживаемый клиент в памяти для возврата; RAM продолжает использоваться.','Опционально и выключено по умолчанию для каждой сборки. Поддерживается Fabric 1.21.1 и 1.21.11; это не обещание для всех версий Minecraft.','В настройках поддерживаемой сборки явно включите Warm Return.|Запустите игру и проверьте доступность режима. Перед ожиданием выйдите из мира/сервера к безопасному экрану.|Используйте доступное действие возврата в лаунчер, затем вернитесь в сохранённый клиент.|Следите за памятью: Minecraft остаётся процессом в RAM.|Для освобождения ресурсов используйте полный выход из игры, а не только скрытие окна.','Возврат возможен без нового холодного запуска поддерживаемого клиента. Активную сессию мира/сервера нельзя считать безопасно завершённой скрытием.','Если версия/загрузчик не поддерживаются, режим недоступен. Сохранённый клиент может занимать значительную память; это не бесплатное ускорение FPS.','При проблеме полностью закройте Minecraft и отключите опцию для этой сборки. Убедитесь, что процесс игры завершён, перед заменой файлов/профиля.'],
['Warm Return and exiting completely','Warm Return keeps a supported client in memory for returning later; it continues using RAM.','Per-instance opt-in, off by default. Fabric 1.21.1 and 1.21.11 are supported; this is not a promise for every Minecraft version.','Explicitly enable Warm Return in a supported instance’s settings.|Launch and check availability. Before entering standby, leave the world/server for a safe screen.|Use the available return-to-launcher action, then return to the retained client.|Monitor memory: Minecraft remains a process in RAM.|Use Exit completely to free resources instead of merely hiding its window.','A supported retained client can return without a new cold launch. Hiding a world/server session does not safely end it.','Unsupported versions/loaders cannot use this mode. The retained client may consume substantial memory; this is not a claim of increased FPS.','If problems occur, exit Minecraft completely and disable the option for that instance. Verify the game process has ended before replacing files or changing its profile.']);
add('profile-switch','profiles','твинки|alt accounts|switch|переключение профиля',
['Переключение игрового профиля внутри игры','На поддерживаемом клиенте можно сменить игровой профиль с учётом безопасного состояния игры.','Fabric 1.21.1 и 1.21.11. Профиль должен быть настроен заранее; переключение не переносит доступ к аккаунту Minerva и не обходит серверную авторизацию.','Заранее добавьте нужные игровые профили в Minerva.|На поддерживаемой сборке откройте доступное управление профилями. Перед сменой выйдите из сервера/мира.|Выберите профиль и подтвердите смену, если клиент предлагает подтверждение.|Проверьте имя выбранного игрока до повторного подключения. Для Microsoft может потребоваться актуальная авторизация.','Следующее подключение использует выбранный поддерживаемый игровой профиль. Веб-аккаунт облака остаётся отдельным.','Нельзя обещать безопасную смену личности посреди активной сетевой сессии. Сервер может иметь собственные правила и ограничения профилей.','Если смена не удалась, полностью закройте игру и выберите профиль в лаунчере перед запуском. Не отправляйте список аккаунтов и токены в отчёте.'],
['Switch game profiles in game','Supported clients can change game profiles while respecting the game’s safe state.','Fabric 1.21.1 and 1.21.11. Configure profiles first. Switching does not transfer Minerva cloud-account access or bypass server authentication.','Add the required game profiles in Minerva ahead of time.|Open available profile controls in a supported instance. Leave the world/server before changing profiles.|Select a profile and confirm where the client requests confirmation.|Check the selected player name before reconnecting. Microsoft profiles may need current authentication.','The next connection uses the selected supported game profile. The cloud web account remains separate.','Do not assume identity can safely change during an active network session. Servers may apply their own profile rules and restrictions.','If switching fails, exit the game completely and choose a profile in the launcher before relaunching. Do not include account lists or tokens in reports.']);
add('offline','profiles','offline|нет интернета|без сети|локальные файлы',
['Запуск из локальных файлов и без сети','Режим пропускает сетевую проверку описаний файлов и автоматическую замену, но не создаёт отсутствующий runtime.','Minecraft, загрузчик, Java, библиотеки и контент должны быть подготовлены заранее. Для Microsoft требования авторизации не меняются. Облако и каталоги без сети недоступны.','При рабочем интернете выполните успешный запуск нужной сборки и закройте игру.|На её карточке включите «Запуск из локальных файлов». Прочитайте пояснение о пропуске проверки.|Запустите уже установленную игру. Для локального профиля учитывайте ограничения серверов.|Вернувшись в сеть, выключите режим, если хотите снова выполнять обычные проверки и замены.','Используются имеющиеся локальные файлы. Это не подтверждение доступности всех сетевых функций офлайн.','Недостающие библиотеки не появятся без скачивания. Режим не продлевает Microsoft-сессию и не даёт лицензию.','Восстановите соединение, вернитесь к обычному запуску и исправьте отсутствующие файлы. Перед ручной заменой сохраните рабочие файлы и миры.'],
['Launch from local files and offline','This mode skips online file-description checks and automatic replacement; it does not create a missing runtime.','Minecraft, loader, Java, libraries and content must already be prepared. Microsoft authentication requirements remain unchanged. Cloud and catalogs need a connection.','While online, complete a successful launch of the intended instance and close the game.|Enable Launch from local files on its card and read the explanation of skipped checks.|Launch the installed game. Local profiles still have server-access limitations.|Disable the mode when back online if you want normal checks and replacements again.','Existing local files are used. This does not establish offline availability of all network features.','Missing libraries cannot be downloaded without a connection. This mode does not extend a Microsoft session or grant a licence.','Restore the connection, return to normal launching and repair missing files. Preserve working files and worlds before manual replacement.']);
add('contact','profiles','поддержка|support|bug|вопрос|developer',
['Связаться с разработчиком','Отправьте текстовое обращение и читайте ответы на сайте; внешние уведомления не подключены.','Не отправляйте пароли, токены, приватные share/invite-ссылки и необработанные логи. Вложения и автоматические скриншоты не принимаются.','Откройте кнопку вопроса внизу страницы. Выберите категорию и напишите тему.|Добавьте шаги воспроизведения, ожидаемый и фактический результат, версию Minerva и безопасный фрагмент ошибки.|Отправьте форму. При сетевой ошибке текст остаётся в текущей форме; повтор использует тот же ключ отправки.|В аккаунте откройте «Мои обращения». Гость должен сохранить приватную tracking-ссылку после отправки.|Проверяйте ответ в веб-интерфейсе, отвечайте в той же переписке и закройте вопрос после решения.','Обращение имеет номер и историю. Сообщения не являются анонимной телеметрией; их видит владелец сервиса.','Без аккаунта потеря tracking-ссылки означает потерю доступа. Не обещаются e-mail, Telegram или мгновенный онлайн-ответ. При изменившейся ревизии обновите переписку.','Не храните ссылку на общем компьютере. Для удаления обратитесь к владельцу через ту же переписку; сроки хранения и ограничения резервных копий описаны в privacy.'],
['Contact the developer','Send a text request and read replies on the website. External notifications are not connected.','Do not send passwords, tokens, private share/invite links or unreviewed logs. Attachments and automatic screenshots are not accepted.','Open the question button at the bottom of the page. Select a category and enter a subject.|Include reproduction steps, expected and actual results, the Minerva version and a safe error excerpt.|Submit. After a network error, text stays in the current form and retry uses the same request key.|Open My requests in your account. Guests must save the private tracking link shown after submission.|Read replies in the web interface, respond in the same thread and close it when resolved.','The request has a number and history. Messages are not anonymous telemetry; the service owner can read them.','Losing a guest tracking link means losing access. Email, Telegram and immediate online responses are not promised. Refresh the conversation after a revision conflict.','Do not store the link on a shared computer. Request deletion through the same conversation; privacy explains retention and backup limitations.']);


// Reviewed against published 0.4.30–0.4.34 release sources on 2026-10-19.
add("migration-prism","instances","Prism|MultiMC|перенос|импорт|instance.cfg|mmc-pack.json",["Перенос сборки из Prism или MultiMC", "Скопируйте игровые данные в отдельную сборку Minerva, сохранив оригинал.", "Закройте исходную игру. Нужны свободное место и резервная копия важных миров.", "Откройте «Сборки» → «Импорт» → «Из другого лаунчера».|Выберите папку экземпляра Prism/MultiMC с instance.cfg и mmc-pack.json либо его внутреннюю папку .minecraft или minecraft.|Проверьте имя, распознанную версию Minecraft, загрузчик и состав копирования.|Запустите перенос. Minerva создаёт отдельную копию поддерживаемых игровых данных; аккаунты, токены и команды запуска не переносятся.|Подготовьте Java и файлы Minecraft при первом запуске. Сначала проверьте меню и тестовую копию мира.", "Есть отдельная сборка Minerva; исходная папка Prism/MultiMC остаётся на месте.", "Произвольная папка может не содержать метаданных экземпляра. Совместимость всех модов не гарантируется переносом файлов.", "Сохраните оригинал и резервную копию saves. При ошибке исправляйте новую сборку или повторите импорт, не удаляя исходную."],["Import a Prism or MultiMC instance", "Copy game data into a separate Minerva instance while keeping the source.", "Close the source game. You need free disk space and a backup of important worlds.", "Open Instances → Import → From another launcher.|Choose the Prism/MultiMC instance folder containing instance.cfg and mmc-pack.json, or its inner .minecraft or minecraft directory.|Review the name, detected Minecraft version, loader and selected game data.|Start import. Minerva copies supported game data separately; accounts, tokens and launch commands are not imported.|Prepare Java and Minecraft files on first launch. Test the menu and a copy of a world first.", "You have a separate Minerva instance; the original Prism/MultiMC folder stays in place.", "An arbitrary folder may lack instance metadata. Copying files does not guarantee compatibility of all mods.", "Keep the source and a saves backup. Repair or retry the new copy without deleting the original."]);
for(const a of articles.filter(a=>a.slug==="migration-prism")){a.minLauncherVersion="0.4.30";a.verifiedAt='2026-10-19';}
add("shared-folders","instances","общие папки|shared folders|schematics|emotes|screenshots|saves",["Общие папки между сборками", "Подключайте разрешённые игровые папки к общей библиотеке.", "Закройте запущенные игры. Общий мир открывайте только в одной игре одновременно.", "Откройте настройки общей библиотеки папок для нужной сборки.|Выберите schematics, emotes, sounds/sound, saves, screenshots или разрешённую собственную папку.|Проверьте выбранную библиотеку и подтвердите подключение. Существующие локальные файлы сохраняются отдельно; миры автоматически не объединяются.|Перед началом игры проверьте содержимое папки. Для независимой копии используйте полное клонирование или ZIP-экспорт.|Для возврата локальной папки отключите её от библиотеки при закрытой игре.", "Подключённые сборки используют одну библиотеку. Удаление сборки не удаляет саму библиотеку.", "Изменение подключения блокируется во время работы игры. Общая папка не является резервной копией.", "Не удаляйте библиотеку для отключения сборки. Отключите связь штатным действием и проверьте возвращённые локальные данные."],["Share folders between instances", "Connect allowed game folders to a shared library.", "Close running games. Open a particular shared world in only one game at a time.", "Open shared-folder settings for the intended instance.|Choose schematics, emotes, sounds/sound, saves, screenshots or an allowed custom folder.|Review the library and confirm connection. Existing local files are preserved separately; worlds are never merged automatically.|Inspect the folder before playing. For an independent copy, use full cloning or ZIP export.|Disconnect the folder with the game closed to restore the local folder.", "Connected instances use one library. Deleting an instance does not delete that library.", "Connection changes are blocked while games are running. A shared folder is not a backup.", "Do not delete the library to disconnect an instance. Use the disconnect action and inspect restored local data."]);
for(const a of articles.filter(a=>a.slug==="shared-folders")){a.minLauncherVersion="0.4.34";a.verifiedAt='2026-10-19';}
add("clone-instance","instances","клонирование|clone|копия|full copy",["Клонирование сборки", "Выберите копирование контента или полную независимую копию.", "Закройте игру и проверьте свободное место; сохраните важные миры отдельно.", "Откройте действие клонирования нужной сборки.|Выберите только контент для модов, ресурспаков и шейдерпаков либо полную копию для настроек, миров, карт и скриншотов.|Укажите имя и дождитесь завершения копирования.|Проверьте новую сборку отдельно от исходной. Полная копия материализует подключённые общие данные независимо.", "Клон независим от оригинала.", "Разные версии Minecraft не делают произвольные моды и конфиги совместимыми. Неудачное копирование не считается готовой сборкой.", "Исходную сборку не удаляйте до проверки копии и миров."],["Clone an instance", "Choose content only or a full independent copy.", "Close the game, check free disk space and back up important worlds separately.", "Open the intended instance’s clone action.|Choose content only for mods, resource packs and shaders, or full copy for settings, worlds, maps and screenshots.|Name the copy and wait for copying to finish.|Test the new instance separately. Full copies materialize connected shared data independently.", "The clone is independent of the original.", "Different Minecraft versions do not make arbitrary mods or configs compatible. A failed copy is not a ready instance.", "Keep the source until the new instance and its worlds have been checked."]);
for(const a of articles.filter(a=>a.slug==="clone-instance")){a.minLauncherVersion="0.4.33";a.verifiedAt='2026-10-19';}
add("appearance","profiles","скины|плащи|HD|Premium|appearance|skin|cape|значки",["Скины, плащи и внешность Minerva", "Официальный облик Microsoft и переопределение Minerva настраиваются отдельно.", "Компонент Minerva: Fabric 1.21.1, 1.21.4, 1.21.10, 1.21.11, 26.2 и 26.3. Применение HD-скина требует Minerva Premium.", "Откройте редактор внешности игрового профиля.|Выберите официальный скин/доступный плащ Microsoft либо локальный файл для библиотеки.|Для отдельного скина Minerva войдите в Minerva и выберите нужный профиль. Перед изменением проверяется сессия.|Для HD-скина используйте Premium. Доступны два сохраняемых слота по никам.|Проверьте внешний вид и переключатели слоёв на поддерживаемом клиенте с компонентом.", "Minerva-скин является отдельным переопределением; официальный Microsoft-скин не заменяется. Просмотр доступен всем пользователям компонента.", "Вход Microsoft не заменяет вход Minerva. Если игра уже запущена, для подключения к сеансу Minerva может понадобиться перезапуск сборки.", "Сохраните исходный PNG. Для снятия переопределения войдите в соответствующий аккаунт Minerva."],["Skins, capes and Minerva appearance", "Official Microsoft appearance and Minerva overrides are configured separately.", "Minerva component: Fabric 1.21.1, 1.21.4, 1.21.10, 1.21.11, 26.2 and 26.3. Applying HD skins requires Minerva Premium.", "Open the game profile’s appearance editor.|Choose an official Microsoft skin/owned cape or a local library file.|For a separate Minerva skin, sign in to Minerva and select the intended profile. The session is checked before changes.|HD skins require Premium. Two persistent nickname slots are available.|Inspect the look and layer toggles in a supported client with the component.", "A Minerva skin is a separate override; the official Microsoft skin is not replaced. All component users can view it.", "Microsoft sign-in does not replace Minerva sign-in. A running instance may need restarting to connect to the Minerva session.", "Keep your original PNG. Sign in to the corresponding Minerva account to remove its override."]);
